draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 25, 25, 0, 2 * Math.PI);
  ctx.stroke();

  // tail
  let tailX = W/2;
  let tailY = H/2 + 75;
  let tailAngle = Math.sin(t) * Math.PI / 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(tailX + Math.cos(tailAngle) * 50, tailY + Math.sin(tailAngle) * 25);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 40);
  ctx.lineTo(W/2 - 30, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 40);
  ctx.lineTo(W/2 + 30, H/2 - 60);
  ctx.stroke();

  ctx.restore();
}
